package cz.systematic.money;
import android.content.Context;import java.net.*;import java.io.*;import org.json.*;
final class WidgetAPI {
 static JSONObject request(Context c,String path,JSONObject body)throws Exception{JSONObject creds=WidgetStore.read(c);URL url=new URL(creds.getString("origin")+"/api/widget"+path);if(!url.getProtocol().equals("https"))throw new IOException("Vyžadováno HTTPS");HttpURLConnection conn=(HttpURLConnection)url.openConnection();conn.setInstanceFollowRedirects(false);conn.setConnectTimeout(10000);conn.setReadTimeout(15000);conn.setRequestProperty("Authorization","Bearer "+creds.getString("token"));try{if(body!=null){conn.setRequestMethod("POST");conn.setDoOutput(true);conn.setRequestProperty("Content-Type","application/json");try(OutputStream out=conn.getOutputStream()){out.write(body.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}}int code=conn.getResponseCode();if(code==401){WidgetStore.clear(c);throw new IOException("Připojte widget znovu v aplikaci");}if(code<200||code>=300)throw new IOException("Akce není dostupná ("+code+")");try(InputStream in=conn.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1){out.write(buffer,0,n);if(out.size()>100000)throw new IOException("Neplatná odpověď");}return new JSONObject(out.toString("UTF-8"));}}finally{conn.disconnect();}}
}
